  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "gatsby-guide",
      "components": [
        {
          "id": "root",
          "component": "Column",
          "children": [
            "title",
            "summary-card",
            "discussion-questions-card",
            "playlist-card"
          ],
          "justify": "start",
          "align": "center"
        },
        {
          "id": "title",
          "component": "Text",
          "text": "The Great Gatsby: A Guide",
          "variant": "h1"
        },
        {
          "id": "summary-card",
          "component": "Card",
          "child": "summary-content"
        },
        {
          "id": "summary-content",
          "component": "Column",
          "children": [
            "summary-title",
            "summary-text"
          ],
          "align": "start"
        },
        {
          "id": "summary-title",
          "component": "Text",
          "text": "Summary",
          "variant": "h3"
        },
        {
          "id": "summary-text",
          "component": "Text",
          "text": "This guide provides a structured approach to discussing F. Scott Fitzgerald's masterpiece, focusing on the decay of the American Dream and the power of symbols."
        },
        {
          "id": "discussion-questions-card",
          "component": "Card",
          "child": "discussion-questions-content"
        },
        {
          "id": "discussion-questions-content",
          "component": "Column",
          "children": [
            "discussion-questions-title",
            "plot-summary-title",
            "plot-summary-text",
            "discussion-questions-list"
          ],
          "align": "start"
        },
        {
          "id": "discussion-questions-title",
          "component": "Text",
          "text": "Discussion Questions",
          "variant": "h3"
        },
        {
          "id": "plot-summary-title",
          "component": "Text",
          "text": "Plot Summary",
          "variant": "h4"
        },
        {
          "id": "plot-summary-text",
          "component": "Text",
          "text": "Set in the summer of 1922, the story follows Nick Carraway, who moves to Long Island and becomes entangled in the life of his mysterious neighbor, Jay Gatsby. Gatsby is a self-made millionaire obsessed with reuniting with his former flame, Daisy Buchanan, who is married to the wealthy but unfaithful Tom. As Gatsby uses his lavish parties to draw Daisy in, the facade of his wealth and the purity of his dream begin to crumble. The narrative explores themes of social stratification and the moral void of the Jazz Age, culminating in a series of tragic events that reveal the hollowness of the upper class and the impossibility of recapturing the past."
        },
        {
          "id": "discussion-questions-list",
          "component": "List",
          "direction": "vertical",
          "children": [
            "q1",
            "q2",
            "q3",
            "q4",
            "q5"
          ]
        },
        {
          "id": "q1",
          "component": "Text",
          "text": "1. How does Gatsby’s pursuit of the American Dream differ from the reality of the social class he tries to join?"
        },
        {
          "id": "q2",
          "component": "Text",
          "text": "2. What does the 'Green Light' at the end of Daisy’s dock represent at the beginning versus the end of the novel?"
        },
        {
          "id": "q3",
          "component": "Text",
          "text": "3. Analyze the Valley of Ashes: How does it serve as a symbolic contrast to East and West Egg?"
        },
        {
          "id": "q4",
          "component": "Text",
          "text": "4. Do any characters in the book truly achieve 'The American Dream', or is it depicted as an inherent illusion?"
        },
        {
          "id": "q5",
          "component": "Text",
          "text": "5. How does the recurring motif of 'The Eyes of Doctor T.J. Eckleburg' function as a commentary on the characters' morality?"
        },
        {
          "id": "playlist-card",
          "component": "Card",
          "child": "playlist-content"
        },
        {
          "id": "playlist-content",
          "component": "Column",
          "children": [
            "playlist-title",
            "playlist-audio1",
            "playlist-audio2",
            "playlist-audio3"
          ],
          "align": "start"
        },
        {
          "id": "playlist-title",
          "component": "Text",
          "text": "Background Jazz Playlist",
          "variant": "h3"
        },
        {
          "id": "playlist-audio1",
          "component": "AudioPlayer",
          "url": "/audio/rhapsody_in_blue.mp3",
          "description": "Rhapsody in Blue by George Gershwin (1924)"
        },
        {
          "id": "playlist-audio2",
          "component": "AudioPlayer",
          "url": "/audio/west_end_blues.mp3",
          "description": "West End Blues by Louis Armstrong (1928)"
        },
        {
          "id": "playlist-audio3",
          "component": "AudioPlayer",
          "url": "/audio/the_charleston.mp3",
          "description": "The Charleston by James P. Johnson (1923)"
        }
      ]
    }
  }
]
