    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "tent-comparison-surface",
      "components": [
        {
          "id": "root",
          "component": "Column",
          "children": [
            "title",
            "summary",
            "structural-comparison-title",
            "structural-comparison-table",
            "recommendation-title",
            "recommendation-text",
            "essential-gear-title",
            "essential-gear-list"
          ],
          "justify": "start",
          "align": "stretch"
        },
        {
          "id": "title",
          "component": "Text",
          "text": "Tent Comparison: 3-Season vs. 4-Season",
          "variant": "h1"
        },
        {
          "id": "summary",
          "component": "Text",
          "text": "The primary difference lies in the environment they are designed to withstand. 3-season tents prioritize ventilation and weight savings for spring, summer, and fall, while 4-season tents (winter tents) are built to endure heavy snow and high winds.",
          "variant": "body"
        },
        {
          "id": "structural-comparison-title",
          "component": "Text",
          "text": "Structural Comparison",
          "variant": "h2"
        },
        {
          "id": "structural-comparison-table",
          "component": "Column",
          "children": [
            "structural-comparison-header",
            "structural-comparison-poles",
            "structural-comparison-mesh",
            "structural-comparison-snow-load"
          ],
          "justify": "start",
          "align": "stretch"
        },
        {
          "id": "structural-comparison-header",
          "component": "Row",
          "children": [
            "structural-comparison-feature-header",
            "structural-comparison-3season-header",
            "structural-comparison-4season-header"
          ],
          "justify": "spaceBetween",
          "align": "center"
        },
        {
          "id": "structural-comparison-feature-header",
          "component": "Text",
          "text": "Feature",
          "variant": "h4"
        },
        {
          "id": "structural-comparison-3season-header",
          "component": "Text",
          "text": "3-Season Tent",
          "variant": "h4"
        },
        {
          "id": "structural-comparison-4season-header",
          "component": "Text",
          "text": "4-Season Tent",
          "variant": "h4"
        },
        {
          "id": "structural-comparison-poles",
          "component": "Row",
          "children": [
            "structural-comparison-poles-label",
            "structural-comparison-poles-3season",
            "structural-comparison-poles-4season"
          ],
          "justify": "spaceBetween",
          "align": "center"
        },
        {
          "id": "structural-comparison-poles-label",
          "component": "Text",
          "text": "Pole Material/Thickness",
          "variant": "body"
        },
        {
          "id": "structural-comparison-poles-3season",
          "component": "Text",
          "text": "Thinner aluminum (8.5mm - 9mm); focus on flexibility.",
          "variant": "body"
        },
        {
          "id": "structural-comparison-poles-4season",
          "component": "Text",
          "text": "Thicker, high-grade aluminum (9.5mm+); more intersection points for rigidity.",
          "variant": "body"
        },
        {
          "id": "structural-comparison-mesh",
          "component": "Row",
          "children": [
            "structural-comparison-mesh-label",
            "structural-comparison-mesh-3season",
            "structural-comparison-mesh-4season"
          ],
          "justify": "spaceBetween",
          "align": "center"
        },
        {
          "id": "structural-comparison-mesh-label",
          "component": "Text",
          "text": "Canopy Mesh %",
          "variant": "body"
        },
        {
          "id": "structural-comparison-mesh-3season",
          "component": "Text",
          "text": "High mesh percentage (50-70%) for airflow and weight reduction.",
          "variant": "body"
        },
        {
          "id": "structural-comparison-mesh-4season",
          "component": "Text",
          "text": "Minimal mesh; mostly solid fabric (nylon/polyester) to retain heat and block spindrift.",
          "variant": "body"
        },
        {
          "id": "structural-comparison-snow-load",
          "component": "Row",
          "children": [
            "structural-comparison-snow-load-label",
            "structural-comparison-snow-load-3season",
            "structural-comparison-snow-load-4season"
          ],
          "justify": "spaceBetween",
          "align": "center"
        },
        {
          "id": "structural-comparison-snow-load-label",
          "component": "Text",
          "text": "Snow Load Capacity",
          "variant": "body"
        },
        {
          "id": "structural-comparison-snow-load-3season",
          "component": "Text",
          "text": "Low; steep walls and mesh can sag or collapse under heavy snow.",
          "variant": "body"
        },
        {
          "id": "structural-comparison-snow-load-4season",
          "component": "Text",
          "text": "High; rounded dome shapes and sturdy frames shed snow and support weight.",
          "variant": "body"
        },
        {
          "id": "recommendation-title",
          "component": "Text",
          "text": "Scottish Highlands Recommendation (July)",
          "variant": "h2"
        },
        {
          "id": "recommendation-text",
          "component": "Text",
          "text": "July in the Highlands is characterized by rain and strong winds, but not heavy snow. A 3-season tent offers the necessary ventilation to combat condensation and is significantly lighter for long treks. However, ensure the tent has a sturdy \"semi-geodesic\" or \"tunnel\" design, as Highland winds can be severe even in summer.",
          "variant": "body"
        },
        {
          "id": "essential-gear-title",
          "component": "Text",
          "text": "Essential Gear for Scotland July",
          "variant": "h3"
        },
        {
          "id": "essential-gear-list",
          "component": "List",
          "direction": "vertical",
          "children": [
            "essential-gear-item-1",
            "essential-gear-item-2",
            "essential-gear-item-3"
          ]
        },
        {
          "id": "essential-gear-item-1",
          "component": "Text",
          "text": "Sturdy tent stakes (for boggy or rocky ground).",
          "variant": "body"
        },
        {
          "id": "essential-gear-item-2",
          "component": "Text",
          "text": "High-quality rain fly with a high hydrostatic head rating.",
          "variant": "body"
        },
        {
          "id": "essential-gear-item-3",
          "component": "Text",
          "text": "Bug mesh (essential for protection against the infamous Highland midges).",
          "variant": "body"
        }
      ]
    }
  }
]
