          "align": "stretch"
        },
        {
          "id": "point-2-title",
          "component": "Text",
          "text": "2. Point Multipliers on Dining (Weight: 25%)",
          "variant": "h3"
        },
        {
          "id": "point-2-description",
          "component": "Text",
          "text": "With a $2,000 monthly spend on travel/dining, a 3x or 4x multiplier translates to 72,000 - 96,000 points annually. In Tokyo, a food mecca, this is where you will accumulate the most rewards.",
          "variant": "body"
        },
        {
          "id": "framework-point-3",
          "component": "Column",
          "children": [
