          "component": "Text",
          "text": "Evaluate if the \"effective cost\" is low. If a $550 card offers $300 in travel credits and $200 in dining credits, the $50 net cost is easily justified by the other perks.",
          "variant": "body"
        },
        {
          "id": "framework-point-4",
          "component": "Column",
          "children": [
            "point-4-title",
            "point-4-description"
          ],
