        {
          "id": "point-4-title",
          "component": "Text",
          "text": "4. Lounge Access (Weight: 15%)",
          "variant": "h3"
        },
        {
          "id": "point-4-description",
          "component": "Text",
          "text": "Important for the long-haul flight to Tokyo (approx. 11-14 hours from the US). Access to Priority Pass or carrier-specific lounges (like JAL/ANA partners) significantly improves the transit experience.",
          "variant": "body"
        },
        {
          "id": "framework-point-5",
          "component": "Column",
          "children": [
            "point-5-title",
            "point-5-description"
          ],
          "justify": "start",
          "align": "stretch"
        },
        {
          "id": "point-5-title",
          "component": "Text",
          "text": "5. Global Entry / TSA PreCheck Credit (Weight: 10%)",
          "variant": "h3"
