          "component": "Column",
          "children": [
            "recommendation-title",
            "recommendation-text"
          ],
          "justify": "start",
          "align": "stretch"
        },
        {
          "id": "recommendation-title",
          "component": "Text",
          "text": "Recommended Weighting for $2,000 Monthly Spend",
          "variant": "h2"
        },
        {
          "id": "recommendation-text",
          "component": "Text",
          "text": "Given your high dining and travel spend, you should prioritize Point Multipliers and No Foreign Transaction Fees. A card with 4x on dining will yield enough points for a free round-trip flight to Japan within 12-18 months of regular spending.",
