text:
[
  {
    "createSurface": {
      "surfaceId": "chair-comparison",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    },
    "version": "v0.9"
  },
  {
    "updateComponents": {
      "surfaceId": "chair-comparison",
      "components": [
        {
          "id": "root",
          "component": "Column",
          "children": [
            "header",
            "comparison-section",
            "actions"
          ],
          "align": "stretch"
        },
        {
          "id": "header",
          "component": "Text",
          "text": "Herman Miller Aeron vs. Steelcase Gesture",
          "variant": "h1"
        },
        {
          "id": "comparison-section",
          "component": "Tabs",
          "tabs": [
            {
              "title": "Summary",
              "child": "summary-content"
            },
            {
              "title": "Ergonomic Features",
              "child": "ergonomic-features"
            }
          ]
        },
        {
          "id": "summary-content",
          "component": "Column",
          "children": [
            "summary-text"
          ],
          "align": "stretch"
        },
        {
          "id": "summary-text",
          "component": "Text",
          "text": "The Herman Miller Aeron is a classic mesh task chair focused on suspended support, while the Steelcase Gesture is designed for modern tech users, supporting a wide range of postures and device-usage styles."
        },
        {
          "id": "ergonomic-features",
          "component": "Column",
          "children": [
            "lumbar-support",
            "armrest-movement",
            "tilt-options"
          ],
          "align": "stretch"
        },
        {
          "id": "lumbar-support",
          "component": "Card",
          "child": "lumbar-support-content"
        },
        {
          "id": "lumbar-support-content",
          "component": "Column",
          "children": [
            "lumbar-support-header",
            "lumbar-support-aeron",
            "lumbar-support-gesture"
          ],
          "align": "stretch"
        },
        {
          "id": "lumbar-support-header",
          "component": "Text",
          "text": "Lumbar Support",
          "variant": "h3"
        },
        {
          "id": "lumbar-support-aeron",
          "component": "Text",
          "text": "- Aeron (Size B): Features the PostureFit SL system. It uses two adjustable pads that stabilize the sacrum and support the lumbar region of the spine to mimic a standing posture."
        },
        {
          "id": "lumbar-support-gesture",
          "component": "Text",
          "text": "- Gesture: Features \"3D LiveBack\" technology. The backrest automatically contours to mimic the natural movement of the spine, providing continuous support as you change positions."
        },
        {
          "id": "armrest-movement",
          "component": "Card",
          "child": "armrest-movement-content"
        },
        {
          "id": "armrest-movement-content",
          "component": "Column",
          "children": [
            "armrest-movement-header",
            "armrest-movement-aeron",
            "armrest-movement-gesture"
          ],
          "align": "stretch"
        },
        {
          "id": "armrest-movement-header",
          "component": "Text",
          "text": "Armrest Movement",
          "variant": "h3"
        },
        {
          "id": "armrest-movement-aeron",
          "component": "Text",
          "text": "- Aeron (Size B): 3D Armrests. They adjust for height, depth (sliding forward/backward), and pivot (turning inward/outward). They are attached to the seat back."
        },
        {
          "id": "armrest-movement-gesture",
          "component": "Text",
          "text": "- Gesture: 4D Armrests. Known for the best range in the industry, they adjust for height, width, depth, and 360-degree pivot. They are designed to support users holding mobile devices or tablets."
        },
        {
          "id": "tilt-options",
          "component": "Card",
          "child": "tilt-options-content"
        },
        {
          "id": "tilt-options-content",
          "component": "Column",
          "children": [
            "tilt-options-header",
            "tilt-options-aeron",
            "tilt-options-gesture"
          ],
          "align": "stretch"
        },
        {
          "id": "tilt-options-header",
          "component": "Text",
          "text": "Tilt Options",
          "variant": "h3"
        },
        {
          "id": "tilt-options-aeron",
          "component": "Text",
          "text": "- Aeron (Size B): Standard model includes a Tilt Limiter with three settings (upright, mid-recline, full recline) and a Seat Angle adjustment (Forward Tilt) for engaged tasks."
        },
        {
          "id": "tilt-options-gesture",
          "component": "Text",
          "text": "- Gesture: Features a variable back stop with four positions. It lacks the forward tilt option found on the Aeron but offers a more seamless \"synchro-tilt\" that keeps feet flat on the floor while reclining."
        },
        {
          "id": "actions",
          "component": "Row",
          "children": [
            "view-aeron-button",
            "view-gesture-button"
          ],
          "justify": "center",
          "align": "center"
        },
        {
          "id": "view-aeron-button",
          "component": "Button",
          "child": "view-aeron-text",
          "action": {
            "functionCall": {
              "call": "openUrl",
              "args": {
                "url": "https://www.hermanmiller.com/products/seating/office-chairs/aeron-chairs/"
              },
              "returnType": "void"
            }
          }
        },
        {
          "id": "view-aeron-text",
          "component": "Text",
          "text": "View Aeron"
        },
        {
          "id": "view-gesture-button",
          "component": "Button",
          "child": "view-gesture-text",
          "action": {
            "functionCall": {
              "call": "openUrl",
              "args": {
                "url": "https://www.steelcase.com/products/office-chairs/gesture/"
              },
              "returnType": "void"
            }
          }
        },
