          "action": {
            "functionCall": {
              "call": "openUrl",
              "args": {
                "url": "https://www.hermanmiller.com/products/seating/office-chairs/aeron-chairs/"
              },
              "returnType": "void"
            }
          }
        },
        {
          "id": "view-aeron-text",
          "component": "Text",
          "text": "View Aeron"
