[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "pruning-shears-guide",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "pruning-shears-guide",
      "components": [
        {
          "id": "root",
          "component": "Column",
          "children": [
            "title",
            "differences-design-title",
            "bypass-pruners-desc",
            "anvil-pruners-desc",
            "recommendation-title",
            "recommendation-text",
            "recommendation-reason",
            "why-anvil-damage-title",
            "why-anvil-damage-desc",
            "seattle-tips-title",
            "seattle-tip-1",
            "seattle-tip-2",
            "seattle-tip-3",
            "shop-button"
          ]
        },
        {
          "id": "title",
          "component": "Text",
          "text": "Pruning Shears Guide for Seattle Rose Gardens",
          "variant": "h1"
        },
        {
          "id": "differences-design-title",
          "component": "Text",
          "text": "Differences in Design",
          "variant": "h2"
        },
        {
          "id": "bypass-pruners-desc",
          "component": "Text",
          "text": "Bypass Pruners: These work like scissors, where two sharp blades pass by each other. This creates a clean, precise cut."
        },
        {
          "id": "anvil-pruners-desc",
          "component": "Text",
          "text": "Anvil Pruners: These have one sharp blade that closes down onto a flat metal or plastic plate (the anvil). This works like a knife on a chopping board."
        },
        {
          "id": "recommendation-title",
          "component": "Text",
          "text": "Recommendation for Rose Stems",
          "variant": "h2"
        },
        {
          "id": "recommendation-text",
          "component": "Text",
          "text": "Recommendation: Bypass Pruning Shears"
        },
        {
          "id": "recommendation-reason",
          "component": "Text",
          "text": "Reason: Roses have live green tissue that needs to heal quickly to prevent disease (common in damp Seattle climates). Bypass shears provide a clean slice that leaves the plant's vascular system intact."
        },
        {
          "id": "why-anvil-damage-title",
          "component": "Text",
          "text": "Why Anvil Shears Damage Live Tissue",
          "variant": "h2"
        },
        {
          "id": "why-anvil-damage-desc",
          "component": "Text",
          "text": "Anvil shears use a crushing motion to complete the cut. On live green stems, this crushing action bruises the delicate cambium layer and mashes the stem fibers. This creates a ragged wound that is slow to heal and serves as an entry point for fungi and pests. Anvil shears should only be used for dead, brittle wood where the crushing doesn't matter."
        },
        {
          "id": "seattle-tips-title",
          "component": "Text",
          "text": "Seattle Gardening Tips for Roses",
          "variant": "h2"
        },
        {
          "id": "seattle-tip-1",
          "component": "Text",
          "text": "- Prune in late February or early March when the forsythia blooms."
        },
        {
          "id": "seattle-tip-2",
          "component": "Text",
          "text": "- Always cut at a 45-degree angle, 1/4 inch above an outward-facing bud."
        },
        {
          "id": "seattle-tip-3",
          "component": "Text",
          "text": "- Clean your blades with isopropyl alcohol between plants to prevent the spread of Black Spot or Mildew."
        },
        {
          "id": "shop-button",
          "component": "Button",
          "child": "shop-button-text",
          "action": {
            "functionCall": {
              "call": "openUrl",
              "args": {
                "url": "https://www.felco.com/en_us/products/pruning-shears"
              }
            }
          }
        },
        {
          "id": "shop-button-text",
          "component": "Text",
          "text": "Shop Bypass Pruners"
        }
      ]
    }
  }
]
